    @Override
    protected @NotNull InteractionResult useWithoutItem(@NotNull BlockState state, @NotNull Level level, @NotNull BlockPos pos, @NotNull Player player, @NotNull BlockHitResult hitResult) {
        if (!level.isClientSide()) {
            if (altarStructure == null) {
                initAltarStructure();
            }
            if (player.isCreative() && player.isShiftKeyDown()) {
                for (int dx = -31; dx <= 31; dx++) {
                    for (int dz = -31; dz <= 31; dz++) {
                        BlockPos targetPos = pos.offset(dx, 0, dz);
                        Block targetBlock = altarStructure[dx + 31][dz + 31];
                        level.setBlock(targetPos, targetBlock.defaultBlockState(), 3);
                    }
                }
                return InteractionResult.SUCCESS;
            }
        }

        return InteractionResult.PASS;
    }

    @Override
    protected @NotNull ItemInteractionResult useItemOn(@NotNull ItemStack stack, @NotNull BlockState state, @NotNull Level level, @NotNull BlockPos pos, @NotNull Player player, @NotNull InteractionHand hand, @NotNull BlockHitResult hitResult) {
        if (!level.isClientSide()) {
            if (stack.getItem() instanceof LoliPickaxe || stack.getItem() instanceof SmallLoliPickaxe) {
                for (int dx = -31; dx <= 31; dx++) {
                    for (int dz = -31; dz <= 31; dz++) {
                        if (level.getBlockState(pos.offset(dx, 0, dz)).getBlock() != altarStructure[dx + 31][dz + 31]) {
                            return ItemInteractionResult.FAIL;
                        }
                    }
                }
                for (int dx = -31; dx <= 31; dx++) {
                    for (int dz = -31; dz <= 31; dz++) {
                        level.removeBlock(pos.offset(dx, 0, dz), false);
                    }
                }
                EntityLoli loli = new EntityLoli(ModEntities.LOLI_ENTITY.get(), level);
                loli.setPos(pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5);
                level.addFreshEntity(loli);

                return ItemInteractionResult.SUCCESS;
            }
        }

        return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;
    }

